import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

const categories = [
  {
    id: "frontend",
    label: "Frontend",
    icon: "</>",
    desc: "Modern UI frameworks, styling systems, and responsive design.",
    skills: [
      { name: "React", icon: "⚛️", level: 75, label: "Advanced" },
      { name: "HTML", icon: "🌐", level: 88, label: "Mastery" },
      { name: "CSS", icon: "🎨", level: 82, label: "Mastery" },
      { name: "JavaScript", icon: "🟨", level: 78, label: "Advanced" },
      { name: "Tailwind CSS", icon: "💨", level: 80, label: "Advanced" },
    ],
  },
  {
    id: "backend",
    label: "Backend",
    icon: "⚙️",
    desc: "Server-side frameworks, APIs, and backend architecture.",
    skills: [
      { name: "Python", icon: "🐍", level: 88, label: "Mastery" },
      { name: "Django", icon: "🎯", level: 82, label: "Advanced" },
      { name: "Django REST", icon: "🔗", level: 75, label: "Advanced" },
      { name: "Node.js", icon: "🟩", level: 55, label: "Intermediate" },
    ],
  },
  {
    id: "database",
    label: "Database",
    icon: "🗄️",
    desc: "Relational databases, query optimization, and data modeling.",
    skills: [
      { name: "SQLite", icon: "📦", level: 82, label: "Advanced" },
      { name: "PostgreSQL", icon: "🐘", level: 65, label: "Intermediate" },
      { name: "MySQL", icon: "🐬", level: 60, label: "Intermediate" },
    ],
  },
  {
    id: "tools",
    label: "Tools & DevOps",
    icon: "🛠️",
    desc: "Security tools, version control, and development environment.",
    skills: [
      { name: "Git & GitHub", icon: "🐙", level: 85, label: "Advanced" },
      { name: "Kali Linux", icon: "🐉", level: 78, label: "Advanced" },
      { name: "Burp Suite", icon: "🔍", level: 72, label: "Advanced" },
      { name: "Metasploit", icon: "💣", level: 68, label: "Intermediate" },
      { name: "Nmap", icon: "📡", level: 80, label: "Advanced" },
      { name: "Wireshark", icon: "🦈", level: 65, label: "Intermediate" },
    ],
  },
];

const labelColor = {
  Mastery: "#a3e635",
  Advanced: "#34d399",
  Intermediate: "#60a5fa",
};

export default function Skills() {
  const [active, setActive] = useState("frontend");
  const current = categories.find((c) => c.id === active);

  return (
    <section id="skills" className="py-24 bg-white/[0.02]">
      <div className="max-w-6xl mx-auto px-6">
        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          className="text-center mb-12"
        >
          <div className="flex items-center justify-center gap-3 mb-3">
            <div className="h-px w-10 bg-green-500" />
            <p className="text-green-400 font-code text-xs tracking-widest uppercase">Skills & Arsenal</p>
            <div className="h-px w-10 bg-green-500" />
          </div>
          <h2 className="text-4xl sm:text-5xl font-bold mb-4">
            Technical <span style={{ color: "#a3e635" }}>Expertise</span>
          </h2>
          <p className="text-gray-400 max-w-lg mx-auto text-sm leading-relaxed">
            A categorized, interactive showcase of technologies, frameworks, backend architectures, and developer tooling.
          </p>
        </motion.div>

        {/* Tab buttons */}
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          className="flex flex-wrap justify-center gap-3 mb-8"
        >
          {categories.map((cat) => (
            <button
              key={cat.id}
              onClick={() => setActive(cat.id)}
              className={`flex items-center gap-2 px-5 py-2.5 rounded-full text-sm font-medium border transition-all duration-200 ${
                active === cat.id
                  ? "border-green-500 text-green-400 bg-green-500/10"
                  : "border-white/10 text-gray-400 hover:border-white/20 hover:text-white bg-white/2"
              }`}
            >
              <span className="font-code text-xs">{cat.icon}</span>
              {cat.label}
              <span className={`text-xs px-1.5 py-0.5 rounded-full font-code ${
                active === cat.id ? "bg-green-500 text-black" : "bg-white/10 text-gray-500"
              }`}>
                {cat.skills.length}
              </span>
            </button>
          ))}
        </motion.div>

        {/* Skills panel */}
        <AnimatePresence mode="wait">
          <motion.div
            key={active}
            initial={{ opacity: 0, y: 15 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            transition={{ duration: 0.25 }}
            className="glass rounded-2xl p-6 border border-white/8"
          >
            {/* Panel header */}
            <div className="flex items-center justify-between mb-6">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-green-500/15 border border-green-500/30 flex items-center justify-center font-code text-green-400 text-sm">
                  {current.icon}
                </div>
                <div>
                  <div className="flex items-center gap-2">
                    <h3 className="font-bold text-white">{current.label}</h3>
                    <span className="text-xs px-2 py-0.5 rounded-full bg-green-500/15 text-green-400 border border-green-500/20 font-code">
                      {current.skills.length} Skills
                    </span>
                  </div>
                  <p className="text-xs text-gray-500 mt-0.5">{current.desc}</p>
                </div>
              </div>
            </div>

            {/* Skills grid */}
            <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4">
              {current.skills.map((skill, i) => (
                <motion.div
                  key={skill.name}
                  initial={{ opacity: 0, scale: 0.95 }}
                  animate={{ opacity: 1, scale: 1 }}
                  transition={{ delay: i * 0.06 }}
                  className="bg-white/3 border border-white/6 rounded-xl p-4 hover:border-green-500/20 transition-colors"
                >
                  <div className="flex items-start justify-between mb-3">
                    <div className="w-10 h-10 rounded-lg bg-white/5 border border-white/8 flex items-center justify-center text-xl">
                      {skill.icon}
                    </div>
                    <span
                      className="text-xs font-bold px-2 py-0.5 rounded-full font-code"
                      style={{
                        color: labelColor[skill.label] || "#60a5fa",
                        background: (labelColor[skill.label] || "#60a5fa") + "20",
                        border: `1px solid ${(labelColor[skill.label] || "#60a5fa")}40`,
                      }}
                    >
                      {skill.level}%
                    </span>
                  </div>
                  <p className="font-medium text-white text-sm mb-0.5">{skill.name}</p>
                  <p className="text-xs mb-3" style={{ color: labelColor[skill.label] || "#60a5fa" }}>
                    {skill.label}
                  </p>
                  {/* Progress bar */}
                  <div className="h-1 bg-white/5 rounded-full overflow-hidden">
                    <motion.div
                      className="h-full rounded-full"
                      style={{
                        background: `linear-gradient(90deg, ${labelColor[skill.label] || "#60a5fa"}, ${labelColor[skill.label] || "#60a5fa"}99)`,
                      }}
                      initial={{ width: 0 }}
                      animate={{ width: `${skill.level}%` }}
                      transition={{ duration: 0.8, delay: i * 0.06, ease: "easeOut" }}
                    />
                  </div>
                </motion.div>
              ))}
            </div>
          </motion.div>
        </AnimatePresence>
      </div>

    </section>

  );
}
